116	<script>
117	const ESC = {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"};
118	const esc = s => String(s === null || s === undefined ? "" : s).replace(/[&<>"']/g, c => ESC[c]);
119	const blank = v => (v === null || v === undefined || v === "") ? '<span class="muted">—</span>' : esc(v);
120	
121	const BATCH_FIELDS = [
122	  {key: "source", label: "来源"},
123	  {key: "region", label: "地区"},
124	  {key: "industry", label: "行业"},
125	  {key: "important_date", label: "重要日期", date: true},
126	];
127	
128	let clients = [];
129	const selected = new Set();
130	// 一次批量保存从发出到本次结果处理结束期间为 true：期间只能有这一次请求，
131	// 勾选变化与表单重复提交都不能解除或新增请求。
132	let batchSaving = false;
133	
134	function syncSubmitState() {
135	  const btn = document.getElementById("batch-submit");
136	  btn.disabled = batchSaving || selected.size === 0;
137	  btn.textContent = batchSaving ? "正在保存…" : "保存修改";
