140	async function loadClients() {
141	  // 只在明确读到有效客户列表（真正的空列表也算）时才更新页面；
142	  // 连接错误、非成功状态、响应无法解析或未包含 clients 数组都视为读取失败：
143	  // 保留此前已显示的客户编号、名称与各字段内容，不清空表格、不显示空列表提示。
144	  const note = document.getElementById("clients-load-error");
145	  let list;
146	  try {
147	    const res = await fetch("/api/clients");
148	    if (!res.ok) throw new Error("服务返回非成功状态（HTTP " + res.status + "）");
149	    const data = await res.json();
150	    if (!data || !Array.isArray(data.clients)) {
151	      throw new Error("响应未包含有效的客户列表");
152	    }
153	    list = data.clients;
154	  } catch (err) {
155	    let message = err.message;
156	    if (err instanceof SyntaxError) message = "响应无法解析为有效数据";
157	    if (err instanceof TypeError) message = "无法连接到服务（网络错误）";
158	    note.textContent = "客户列表读取失败：" + message +
159	      "，当前显示的资料可能不是最新内容；保存结果不受影响，稍后刷新页面即可重新读取。";
160	    note.classList.add("on");
161	    // 读取失败期间不能让表格或“还没有客户记录”冒充真实的空列表；
162	    // 此前已渲染的行保留不动，之后真正读到空列表时再由 renderClients 恢复空状态提示。
163	    document.getElementById("clients-empty").classList.remove("on");
164	    throw new Error(message);
165	  }
166	  note.classList.remove("on");
167	  note.textContent = "";
168	  clients = list;
169	  const known = new Set(clients.map(r => r.id));
170	  for (const id of [...selected]) {
171	    if (!known.has(id)) selected.delete(id);
172	  }
173	  renderClients();
174	  renderSelection();
175	}
