462	// 非空文本原因；明细条数与未导入数量一致。任一不满足都返回 null，
463	// 不用 0、空数组或 undefined 补造一份成功报告。
464	function parseImportReport(data) {
465	  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
466	  const importedCount = data.imported_count;
467	  const failedCount = data.failed_count;
468	  if (!isNonNegativeInt(importedCount) || !isNonNegativeInt(failedCount)) return null;
469	  if (!Array.isArray(data.failures) || data.failures.length !== failedCount) return null;
470	  const failures = [];
471	  for (const item of data.failures) {
472	    if (!item || typeof item !== "object") return null;
473	    if (typeof item.row !== "number" || !Number.isInteger(item.row) || item.row <= 0) return null;
474	    if (typeof item.reason !== "string" || !item.reason.trim()) return null;
475	    failures.push({row: item.row, reason: item.reason});
476	  }
477	  return {importedCount, failedCount, failures};
478	}
