480	// 错误状态回复可能是 {error: "..."}，也可能只有一段纯文本错误说明。
481	function readableError(data, raw) {
482	  if (data && typeof data === "object" && !Array.isArray(data) &&
483	      typeof data.error === "string" && data.error.trim()) {
484	    return data.error;
485	  }
486	  const text = (raw || "").trim();
487	  return text ? text.slice(0, 200) : "";
488	}
