495	  if (report.failures.length) {
496	    html += '<div class="failures"><p><b>未导入记录（编号按原文件数据记录，表头不计入）：</b></p><ul>';
497	    html += report.failures.map(f =>
498	      "<li>第 <b>" + esc(f.row) + "</b> 条：" + esc(f.reason) + "</li>").join("");
499	    html += "</ul></div>";
500	  }
501	  return html;
502	}
