1	#!/usr/bin/env node
2	/**
3	 * 首页 CSV 导入结果展示的页面层面回归保障。
4	 *
5	 * 启动真实 app.py 服务（与 smoke_test.py / page_test.mjs 同一后端，不模拟、
6	 * 不改动接口公开行为与现有导入规则），用 Puppeteer 驱动系统 Chrome 打开首页，
7	 * 用真实文件选择框上传 CSV；对「服务返回内容」和「导入后的客户列表读取」分别
8	 * 做请求拦截，逐项验证页面严格区分「拿到完整可靠的导入报告」与「只收到成功
9	 * 状态、结果无法确认」：
10	 *
11	 * A. 完整有效报告：显示报告里的新增/未导入数量，按原文件数据记录编号逐条展示
12	 *    原因（表头不计编号，引号字段内换行不拆记录）；覆盖有效/无效混在同一文件
13	 *    的部分成功、仅表头的合法零新增、全部因重复或字段问题跳过（不得说成整份
14	 *    文件被拒绝）；
15	 * B. 成功状态但回复无法解析、数量不是非负整数（负数/小数/文本/布尔/缺失）、
16	 *    未导入明细缺失或条数不符、明细编号不是正整数或原因不是非空文本：一律
17	 *    显示结果无法确认，提示先核对客户列表再决定是否重新导入；不显示成功数量，
18	 *    不补造零新增/空明细，页面不出现 undefined/NaN；页面也不能凭客户列表的
19	 *    行数推算新增数量；
20	 * C. 已取得有效报告后，随后的客户列表读取失败（连接失败 / 500 / 无法解析 /
21	 *    缺少 clients 数组）不改变已确认的数量与逐条原因：附加列表暂未更新、
22	 *    资料可能不是最新、稍后刷新即可、无需重新导入的提示；旧客户行保留，不被
23	 *    清空、不显示空列表提示；重新打开读取成功后显示实际保存的资料；
24	 * D. 结果处理结束后导入按钮恢复可用、已选文件保留、不会自动再次提交；
25	 * E. 正常导入并成功刷新列表的路径，以及整份文件被明确拒绝（HTTP 400）时
26	 *    原有错误说明与资料不变的行为继续保留；网络失败与其他非成功状态同样按
27	 *    「无法确认」处理。
28	 */
29	import {spawn} from "node:child_process";
30	import {dirname, join} from "node:path";
31	import {fileURLToPath} from "node:url";
32	import {mkdtempSync, mkdirSync, rmSync, writeFileSync} from "node:fs";
33	import {tmpdir} from "node:os";
34	import puppeteer from "puppeteer";
35	
36	const HERE = dirname(fileURLToPath(import.meta.url));
37	const APP = join(HERE, "app.py");
38	const TMP = mkdtempSync(join(tmpdir(), "clientbook-import-page-"));
39	const FAILURES = [];
40	let checkCount = 0;
41	
42	function check(label, cond, detail = "") {
43	  checkCount += 1;
44	  if (cond) {
45	    console.log("PASS", label);
46	  } else {
47	    FAILURES.push({label, detail: typeof detail === "string" ? detail : JSON.stringify(detail)});
48	    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
49	  }
50	}
51	
52	const norm = s => (s || "").replace(/[ \t\r\n]+/g, " ").trim();
53	
54	// ---------------------------------------------------------------------------
55	// 真实 app.py 进程
56	// ---------------------------------------------------------------------------
57	function startApp(label) {
58	  const proc = spawn("python3", [
59	    APP, "serve", "--host", "127.0.0.1", "--port", "0",
60	    "--data-dir", join(TMP, label),
61	  ], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
62	  const port = new Promise((resolve, reject) => {
63	    let buf = "";
64	    const onData = d => {
65	      buf += d.toString();
66	      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
67	      if (m) {
68	        proc.stdout.off("data", onData);
69	        resolve(Number(m[1]));
70	      }
71	    };
72	    proc.stdout.on("data", onData);
73	    proc.on("exit", code => reject(new Error(`app.py 意外退出（${code}）：${buf}`)));
74	  });
75	  return {proc, port};
76	}
77	
78	async function waitReady(base, deadlineMs = 8000) {
79	  const deadline = Date.now() + deadlineMs;
80	  while (Date.now() < deadline) {
81	    try {
82	      const res = await fetch(base + "/health");
83	      if (res.status === 200) return;
84	    } catch { /* 尚未就绪 */ }
85	    await new Promise(r => setTimeout(r, 100));
86	  }
87	  throw new Error("服务未在限定时间内就绪：" + base);
88	}
89	
90	async function stopApp(ctx) {
91	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
92	  const timer = setTimeout(() => {
93	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
94	  }, 2000);
95	  await new Promise(r => ctx.proc.on("exit", r));
96	  clearTimeout(timer);
97	}
98	
99	async function startServer(label) {
100	  const {proc, port: portPromise} = startApp(label);
101	  const base = `http://127.0.0.1:${await portPromise}`;
102	  await waitReady(base);
103	  return {proc, base};
104	}
105	
106	// ---------------------------------------------------------------------------
107	// CSV 构造与后端直连准备数据
108	// ---------------------------------------------------------------------------
109	const csvField = v => `"${String(v).replace(/"/g, '""')}"`;
110	const buildCsv = (header, rows) =>
111	  header.map(csvField).join(",") + "\n" +
112	  rows.map(r => r.map(csvField).join(",")).join("\n") + "\n";
113	
114	async function importCsvDirect(base, csv) {
115	  const res = await fetch(base + "/api/clients/import", {method: "POST", body: csv});
116	  const data = await res.json();
117	  if (res.status !== 200) throw new Error("seed 失败：" + JSON.stringify(data));
118	  return data;
119	}
120	
121	async function seed(base, names) {
122	  const csv = buildCsv(["name"], names.map(n => [n]));
123	  const data = await importCsvDirect(base, csv);
124	  return new Map(data.imported.map(x => [x.name, x.id]));
125	}
126	
127	async function listClients(base) {
128	  const res = await fetch(base + "/api/clients");
129	  return res.json();
130	}
131	
132	// ---------------------------------------------------------------------------
133	// 页面驱动：拦截导入请求与导入后的客户列表读取
134	// ---------------------------------------------------------------------------
135	async function openSession(browser, base) {
136	  const page = await browser.newPage();
137	  const modes = {
138	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
139	    // no-clients 可解析但缺少客户数组
140	    list: "ok",
141	    // importOverride：null = 走真实后端；否则用给定 {status, body, contentType}
142	    importOverride: null,
143	    // importAbort 为 true 时直接断开导入请求（模拟网络错误）
144	    importAbort: false,
145	  };
146	  const counts = {importPosts: 0, listGets: 0};
147	
148	  await page.setRequestInterception(true);
149	  page.on("request", request => {
150	    const url = request.url();
151	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
152	      counts.listGets += 1;
153	      if (modes.list === "close") { request.abort("failed"); return; }
154	      if (modes.list === "500") {
155	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
156	          body: JSON.stringify({error: "模拟的服务错误"})});
157	        return;
158	      }
159	      if (modes.list === "bad-json") {
160	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
161	          body: "<<<not valid json>>>"});
162	        return;
163	      }
164	      if (modes.list === "no-clients") {
165	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
166	          body: JSON.stringify({unexpected: true})});
167	        return;
168	      }
169	      request.continue();
170	      return;
171	    }
172	    if (request.method() === "POST" && url.endsWith("/api/clients/import")) {
173	      counts.importPosts += 1;
174	      if (modes.importAbort) { request.abort("failed"); return; }
175	      if (modes.importOverride) {
176	        const {status, body, contentType} = modes.importOverride;
177	        request.respond({
178	          status,
179	          contentType: contentType || "application/json; charset=utf-8",
180	          body,
181	        });
182	        return;
183	      }
184	    }
185	    request.continue();
186	  });
187	
188	  await page.setCacheEnabled(false);
189	  await page.goto(base + "/", {waitUntil: "networkidle0"});
190	  return {page, modes, counts};
191	}
