193	// 读取导入区域与客户列表的全部可见状态
194	async function importSnap(page) {
195	  return page.evaluate(() => {
196	    const text = sel => document.querySelector(sel)?.textContent.trim() ?? null;
197	    const report = document.getElementById("report");
198	    return {
199	      reportVisible: report.style.display === "block",
200	      banners: [...report.querySelectorAll(".banner")].map(b => ({
201	        cls: b.className,
202	        text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
203	      })),
204	      reportText: report.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
205	      failureItems: [...report.querySelectorAll(".failures li")]
206	        .map(li => li.innerText.replace(/[ \t\r\n]+/g, " ").trim()),
207	      failuresTitle: (() => {
208	        const p = report.querySelector(".failures p");
209	        return p ? p.innerText.replace(/[ \t\r\n]+/g, " ").trim() : null;
210	      })(),
211	      filename: text("#filename"),
212	      submitText: text("#submit-btn"),
213	      submitDisabled: document.getElementById("submit-btn").disabled,
214	      fileCount: document.getElementById("file-input").files.length,
215	      rows: [...document.querySelectorAll("#clients-body tr")].map(tr => ({
216	        id: tr.dataset.id,
217	        // td: 0 勾选框, 1 编号, 2 名称, 3 来源, 4 地区, 5 行业, 6 重要日期
218	        cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
219	      })),
220	      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
221	      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
222	      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
223	      loadErrorText: text("#clients-load-error"),
224	    };
225	  });
226	}
