228	async function uploadCsv(page, name, content) {
229	  // 此版本 Puppeteer 的 uploadFile 只接受本地路径：写到临时目录再通过真实文件选择框上传
230	  const dir = join(TMP, "uploads");
231	  mkdirSync(dir, {recursive: true});
232	  const path = join(dir, name);
233	  writeFileSync(path, content, "utf8");
234	  const input = await page.$("#file-input");
235	  await input.uploadFile(path);
236	  await page.waitForFunction(name => document.getElementById("filename").textContent === name,
237	    {}, name);
238	}
