// 读取并判断 HTTP 错误回复的明确拒绝原因，返回 {reason, unreadable}：
//   - reason 非空：拿到明确、可读的拒绝原因（展示时再去首尾空白）；
//   - reason 为空且 unreadable 为 false：回复能正常读取，但没有可靠原因
//     （空回复、仅空白、可解析成 JSON 却没有非空文本 error——如
//     {"message":"错误"}、null、字符串形式的 JSON，或 error 只有空白/不是文本）；
//   - reason 为空且 unreadable 为 true：回复本身读取失败。
// 只有回复对象中的非空文本 error，或「非空的纯文本错误说明」（原文无法解析成
// JSON 时）才算明确原因；绝不把整个 JSON 结构当作原因展示给用户。
function readRejectReason(res) {
  let raw = "";
  let unreadable = false;
  // res.text() 在连接中断等情况下会拒绝：此时没有任何可靠原因。
  raw = res.text().catch ? null : "";
  return res.text().then(text => {
    raw = text || "";
    let data;
    let parsed = false;
    if (raw.trim()) {
      try {
        data = JSON.parse(raw);
        parsed = true;
      } catch {
        data = null;
      }
    } else {
      data = null;
    }
    // 优先 {error: "..."}：error 必须是非空文本（去掉首尾空白后仍有内容）。
    if (parsed && data && typeof data === "object" && !Array.isArray(data) &&
        typeof data.error === "string" && data.error.trim()) {
      return {reason: data.error.trim(), unreadable: false};
    }
    // 只有回复不是 JSON 结构化数据时，才把纯文本原文当作说明。
    // 能解析成 JSON（含 {"message":...}、null、"…" 等字符串形式的 JSON）
    // 但没有上述 error 的，不能把整个结构当原因。
    if (!parsed) {
      const text2 = raw.trim();
      if (text2) return {reason: text2.slice(0, 200), unreadable: false};
    }
    return {reason: "", unreadable};
  }).catch(() => ({reason: "", unreadable: true}));
}

